import { expect, test, uniqueName } from "../../fixtures";

const invalidCases = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

for (const { field, value } of invalidCases) {
  test(`rejects a vendor with ${field} set to ${JSON.stringify(value)}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
    // Arrange: a valid vendor payload with only the target field made invalid.
    const member = await apiAs("member");
    const payload: Record<string, unknown> = {
      name: uniqueName("Vendor"),
      category: "software",
      contact_email: "billing@vendor-ven02.test",
      [field]: value,
    };

    // Act
    const response = await member.post("/api/vendors", { data: payload });

    // Assert
    expect(response.status()).toBe(422);
    const body = await response.json();
    expect(body.error?.code).toBe("validation_error");
    expect(JSON.stringify(body.error ?? body)).toContain(field);
  });
}
